def hav(a,b):
    r=6371000;p1,p2=math.radians(a[0]),math.radians(b[0]);dl=math.radians(b[1]-a[1]);dp=p2-p1
    return 2*r*math.asin(math.sqrt(math.sin(dp/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2))
out=[]
for code,reg,name,tag,badge,pts,loop in R:
    L=round(sum(hav(a,b) for a,b in zip(pts,pts[1:])))
    out.append({"code":code,"region":reg,"name":name,"tagline":tag,"badge":badge,"lengthM":L,"pts":[[round(a,5),round(b,5)] for a,b in pts]})
json.dump(out,open(sys.argv[1],"w"),ensure_ascii=False,separators=(",",":"))
print(len(out),"routes")
